#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> x(q);
    for (int i = 0; i < q; i++) cin >> x[i];

    for (int k = 0; k < q; k++) {
        int lo = 0, hi = n - 1, found = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (a[mid] == x[k]) {
                found = mid;
                break;
            }
            if (a[mid] < x[k]) lo = mid + 1;
            else hi = mid - 1;
        }
        cout << found << "\n";
    }

    return 0;
}

